from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                else:
                    del cache[key]

            if key not in cache:
                if len(cache) >= capacity:
                    # evict expired entries first if any at front, else LRU
                    # need to evict least recently used entry (regardless of expiry)
                    oldest_key = next(iter(cache))
                    del cache[oldest_key]

            cache[key] = (value, t)
            cache.move_to_end(key)
        else:
            _, t, key = op
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

